238	    /**
239	     * The id of the existing owner this one is a soft duplicate of: an owner with a different
240	     * identity key whose last name sounds the same (soundex) and whose postcode is identical,
241	     * recorded at creation. {@code null} when no such owner existed.
242	     */
243	    public Integer getPossibleDuplicateOf() {
244	        return this.possibleDuplicateOf;
245	    }
246	
247	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
248	        this.possibleDuplicateOf = possibleDuplicateOf;
249	    }
