281	    /**
282	     * The owner's primary identifier: the single business identifier that currently identifies this
283	     * owner to the outside world. Today this is the {@link #getCustomerCode() customerCode}; when the
284	     * customer code is later unified into a member id this is the one place that changes, and every
285	     * consumer (e.g. the {@code OWNER_CREATED} audit event) follows automatically.
286	     */
287	    @Transient
288	    public String getPrimaryIdentifier() {
289	        return this.customerCode;
290	    }
291	
292	    /**
293	     * The owner's locality: the REGION portion of its {@code customerCode} (see
294	     * {@link CustomerCode}), which is the region derived from the postcode or city at creation. This
295	     * disambiguates cities that share a name. Yields {@code "UNKNOWN"} when the owner has no customer
296	     * code or it resolves to no region.
297	     */
298	    @Transient
299	    public String getLocality() {
300	        return CustomerCode.regionOf(this.customerCode);
301	    }
302	
303	    /**
304	     * The owner's IANA timezone, derived from its {@link #getLocality() locality} via the fixed
305	     * region-to-timezone table (see {@link RegionTimezone}). {@code null} when the locality has no
306	     * known timezone.
307	     */
308	    @Transient
309	    public String getTimezone() {
310	        return RegionTimezone.of(this.getLocality());
311	    }
312	
313	    /**
314	     * The owner's check digit: the single Luhn check digit computed over the digits of the
315	     * {@code customerCode}, guarding against transcription errors of the code.
316	     */
317	    @Transient
318	    public int getCheckDigit() {
319	        return Luhn.checkDigit(this.customerCode);
320	    }
321	
322	    /**
323	     * The owner's salutation: the {@link #getTitle() title} honorific followed by a space and the
324	     * last name (e.g. {@code "DR who"}), or just the last name when no title was supplied.
325	     */
326	    @Transient
327	    public String getSalutation() {
328	        return (this.title != null && !this.title.isBlank())
329	                ? this.title + " " + this.getLastName()
330	                : this.getLastName();
331	    }
332	
333	    /**
334	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
335	     * present, otherwise {@code "PHONE"}.
336	     */
337	    @Transient
338	    public String getContactPreference() {
339	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
340	    }
341	
342	    /**
343	     * The owner's telephone formatted for humans: the stored E.164 number rendered as its country
344	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). The
345	     * raw {@link #getTelephone() telephone} stays in compact E.164. See {@link E164}.
346	     */
347	    @Transient
348	    public String getTelephoneDisplay() {
349	        return E164.display(this.telephone);
350	    }
351	
352	    /**
353	     * The owner's age band: {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"} derived from the
354	     * birth date against the registration date (see {@link AgeBand}), or {@code null} when no birth
355	     * date was supplied.
356	     */
357	    @Transient
358	    public String getAgeBand() {
359	        return AgeBand.classify(this.birthDate, this.registrationDate);
360	    }
361	
362	    /**
363	     * The owner's fiscal year: the {@code FY<YY>} label of the fiscal year (starting 1 July)
364	     * containing its business-day-adjusted registration date (see {@link FiscalYear}), or
365	     * {@code null} when no registration date is set.
366	     */
367	    @Transient
368	    public String getFiscalYear() {
369	        return (this.registrationDate != null) ? FiscalYear.label(this.registrationDate) : null;
370	    }
371	
372	    /**
373	     * The owner's identity key: the single derived value all duplicate detection is expressed
374	     * through, the lower-case SHA-256 hex digest of
375	     * {@code <normalizedTelephone>|<lowerEmail>|<soundex(lastName)>}. Two owners are duplicates only
376	     * when their whole identity keys are equal, so household members (same last name and postcode)
377	     * with different telephones have different keys and are not hard duplicates.
378	     */
379	    @Transient
380	    public String getIdentityKey() {
381	        String raw = blankToEmpty(this.telephone) + '|'
382	                + blankToEmpty(this.email).toLowerCase(Locale.ROOT) + '|'
383	                + Soundex.encode(this.getLastName());
384	        return Sha256.lowerHex(raw);
385	    }
386	
387	    private static String blankToEmpty(String value) {
388	        return (value == null) ? "" : value;
389	    }
390	
391	    protected Set<Pet> getPetsInternal() {
392	        if (this.pets == null) {
393	            this.pets = new HashSet<>();
394	        }
395	        return this.pets;
396	    }
397	
398	    protected void setPetsInternal(Set<Pet> pets) {
399	        this.pets = pets;
400	    }
401	
402	    public List<Pet> getPets() {
403	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
404	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
405	        return Collections.unmodifiableList(sortedPets);
406	    }
407	
408	    public void setPets(List<Pet> pets) {
409	        this.pets = new HashSet<>(pets);
410	    }
411	
412	    public void addPet(Pet pet) {
413	        getPetsInternal().add(pet);
414	        pet.setOwner(this);
415	    }
416	
417	    /**
418	     * Return the Pet with the given name, or null if none found for this Owner.
419	     *
420	     * @param name to test
421	     * @return true if pet name is already in use
422	     */
423	    public Pet getPet(String name) {
424	        return getPet(name, false);
425	    }
426	
427	    /**
428	     * Return the Pet with the given name, or null if none found for this Owner.
429	     *
430	     * @param name to test
431	     * @return true if pet name is already in use
432	     */
433	    public Pet getPet(String name, boolean ignoreNew) {
434	        name = name.toLowerCase();
435	        for (Pet pet : getPetsInternal()) {
436	            if (!ignoreNew || !pet.isNew()) {
437	                String compName = pet.getName();
438	                compName = compName.toLowerCase();
439	                if (compName.equals(name)) {
440	                    return pet;
441	                }
442	            }
443	        }
444	        return null;
445	    }
446	
447	    public Pet getPet(Integer petId) {
448	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
449	    }
450	
451	    @Override
452	    public String toString() {
453	        return new ToStringCreator(this)
454	
455	            .append("id", this.getId())
456	            .append("new", this.isNew())
457	            .append("lastName", this.getLastName())
458	            .append("firstName", this.getFirstName())
459	            .append("address", this.address)
460	            .append("city", this.city)
461	            .append("telephone", this.telephone)
462	            .toString();
463	    }
464	}
