1	package org.springframework.samples.petclinic.model;
2	
3	/**
4	 * Membership scoring for an owner. Loyalty factors accrue points from a base of zero &mdash; an
5	 * email address ({@value #EMAIL_POINTS}), having had no namesakes at creation
6	 * ({@code namesakeCount} of 0, {@value #NO_NAMESAKE_POINTS}), belonging to a household of
7	 * {@link #LARGE_HOUSEHOLD_SIZE} or more ({@value #LARGE_HOUSEHOLD_POINTS}) and a tenure of more than
8	 * {@link #TENURE_FISCAL_YEARS_FOR_TENURE_POINTS} elapsed fiscal year(s) ({@value #TENURE_POINTS}).
9	 * The total {@link #points} maps to a numeric {@link #levelFor level} of 1&ndash;4.
10	 *
11	 * <p>The email, namesake and household factors are established at creation; only tenure accrues
12	 * afterwards. A newly created owner has zero tenure, so at creation the points cannot exceed 5 and
13	 * the level cannot exceed 3.
14	 */
15	public final class Membership {
16	
17	    /** Elapsed fiscal years of tenure an owner must exceed to earn the tenure points. */
18	    public static final int TENURE_FISCAL_YEARS_FOR_TENURE_POINTS = 1;
19	
20	    /** Households with at least this many members earn the household points. */
21	    public static final int LARGE_HOUSEHOLD_SIZE = 3;
22	
23	    private static final int EMAIL_POINTS = 2;
24	    private static final int NO_NAMESAKE_POINTS = 1;
25	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
26	    private static final int TENURE_POINTS = 3;
27	
28	    private Membership() {
29	    }
30	
31	    /**
32	     * The membership points earned by an owner with the given loyalty factors.
33	     *
34	     * @param hasEmail      whether the owner has an email address
35	     * @param namesakeCount how many existing owners shared the owner's name at creation (0 earns
36	     *                      points); {@code null} earns none
37	     * @param householdSize       how many members the owner's household has
38	     * @param tenureFiscalYears   the owner's tenure counted in elapsed fiscal years
39	     */
40	    public static int points(boolean hasEmail, Integer namesakeCount, int householdSize, long tenureFiscalYears) {
41	        int points = 0;
42	        if (hasEmail) {
43	            points += EMAIL_POINTS;
44	        }
45	        if (Integer.valueOf(0).equals(namesakeCount)) {
46	            points += NO_NAMESAKE_POINTS;
47	        }
48	        if (householdSize >= LARGE_HOUSEHOLD_SIZE) {
49	            points += LARGE_HOUSEHOLD_POINTS;
50	        }
51	        if (tenureFiscalYears > TENURE_FISCAL_YEARS_FOR_TENURE_POINTS) {
52	            points += TENURE_POINTS;
53	        }
54	        return points;
55	    }
56	
57	    /**
58	     * The numeric membership level for a points total: 1 for 0&ndash;1 points, 2 for 2&ndash;3,
59	     * 3 for 4&ndash;5 and 4 for 6 or more.
60	     */
61	    public static int levelFor(int points) {
62	        if (points <= 1) {
63	            return 1;
64	        }
65	        if (points <= 3) {
66	            return 2;
67	        }
68	        if (points <= 5) {
69	            return 3;
70	        }
71	        return 4;
72	    }
73	}
