3	import java.util.Map;
4	
5	/**
6	 * Fixed city-to-region lookup used to derive an owner's locality. Cities not listed
7	 * resolve to {@link #UNKNOWN}.
8	 */
9	public final class CityRegion {
10	
11	    /** The canonical region returned for any city not in the table. */
12	    public static final String UNKNOWN = "UNKNOWN";
13	
14	    private static final Map<String, String> CITY_TO_REGION = Map.of(
15	        "Sydney", "NSW",
16	        "Melbourne", "VIC",
17	        "Brisbane", "QLD");
18	
19	    private CityRegion() {
20	    }
21	
22	    /** The canonical region for {@code city}, or {@link #UNKNOWN} when it is not in the table. */
23	    public static String of(String city) {
24	        return CITY_TO_REGION.getOrDefault(city, UNKNOWN);
25	    }
26	}
