15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    OwnerDto toOwnerDto(Owner owner);
23	
24	    /**
25	     * Maps an {@link Owner} to its DTO and attaches the response-only bulk-signup warning, which is
26	     * computed per request rather than stored on the owner.
27	     */
28	    default OwnerDto toOwnerDto(Owner owner, boolean bulkSignupWarning) {
29	        OwnerDto ownerDto = toOwnerDto(owner);
30	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
31	        return ownerDto;
32	    }
33	
34	    /**
35	     * Maps an {@link Owner} to its DTO and attaches both response-only warnings, which are computed
36	     * per request rather than stored on the owner.
37	     */
38	    default OwnerDto toOwnerDto(Owner owner, boolean bulkSignupWarning, boolean capacityWarning) {
39	        OwnerDto ownerDto = toOwnerDto(owner, bulkSignupWarning);
40	        ownerDto.setCapacityWarning(capacityWarning);
41	        return ownerDto;
42	    }
43	
44	    Owner toOwner(OwnerDto ownerDto);
45	
46	    @Mapping(target = "id", ignore = true)
47	    @Mapping(target = "pets", ignore = true)
48	    Owner toOwner(OwnerFieldsDto ownerDto);
49	
50	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
51	
52	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
53	
54	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
55	        OwnerPageDto ownerPageDto = new OwnerPageDto();
56	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
57	        ownerPageDto.setPage(ownerPage.getNumber());
58	        ownerPageDto.setSize(ownerPage.getSize());
59	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
60	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
61	        return ownerPageDto;
62	    }
63	}
